#ifndef CSM_REWRITE_H
#define CSM_REWRITE_H

#include <stddef.h>

struct path_pair {
	const char *old_path;
	const char *new_path;
};

/*
 * What moves: the variants of the project path (logical and physical) and,
 * for files inside a session directory, that directory itself.
 */
struct rewrite_rules {
	const struct path_pair *projects;
	size_t project_count;
	const char *old_session_dir;	/* NULL when no session directory moves */
	const char *new_session_dir;
};

enum rewrite_kind {
	REWRITE_SESSION,	/* <uuid>.jsonl, one JSON object per line */
	REWRITE_INDEX,		/* sessions-index.json */
	REWRITE_CONFIG		/* .claude.json */
};

enum change_kind {
	CHANGE_REWRITE,		/* a value or a key gets the new path */
	CHANGE_REMOVE,		/* a githubRepoPaths element would repeat */
	CHANGE_CONFLICT,	/* a projects key stays: the new one exists */
	CHANGE_DROP		/* a githubRepoPaths element whose path is gone */
};

struct change {
	enum change_kind kind;
	char *file;
	size_t line;		/* from 1 in .jsonl files, 0 elsewhere */
	char *field;
	char *old_value;
	char *new_value;	/* NULL for CHANGE_REMOVE */
};

struct change_list {
	struct change *items;
	size_t count, cap;
};

/* A githubRepoPaths element: path is NULL when it is not a string. */
struct github_path {
	char *repo;
	char *path;
};

enum {
	REWRITE_OK = 0,
	REWRITE_ERROR = -1,	/* errno tells why */
	REWRITE_INVALID = -2,	/* not valid JSON, so the file stays as it is */
	REWRITE_EXISTS = -3	/* the projects key is already there */
};

char *rewrite_project_path(const struct path_pair *pairs, size_t count,
    const char *value);
int rewrite_text(const char *text, size_t len, enum rewrite_kind kind,
    const struct rewrite_rules *rules, const char *file, size_t line,
    struct change_list *plan, char **out, size_t *out_len);
int rewrite_file(const char *file, enum rewrite_kind kind,
    const struct rewrite_rules *rules, struct change_list *plan, int apply,
    int *backup_done);
void change_list_free(struct change_list *list);
int config_write(const char *file, const char *data, size_t len,
    int *backup_done);
int config_take_project(const char *text, size_t len, const char *key,
    char **value, char **out, size_t *out_len);
int config_put_project(const char *text, size_t len, const char *key,
    const char *value, char **out, size_t *out_len);

int config_github_paths(const char *text, size_t len,
    struct github_path **paths, size_t *count);
void github_paths_free(struct github_path *paths, size_t count);
int config_drop_github(const char *text, size_t len, const char *file,
    const char *drop, struct change_list *plan, char **out, size_t *out_len);

#endif
